// One item per guest who made one of the bookings, for "Read guest profiles".
const ids = new Set($input.all().map(({ json }) => json.userId).filter(Boolean));
return [...ids].map((userId) => ({ json: { userId } }));

// Turns Firestore bookings (from "Read recent bookings") and guest profiles
// (this node's input) into one Google Sheet row per booking.
// Prices and fees must match PAYMENT, CLEANING_FEE and ROOMS in js/store.js.
const ROOMS = {
  house: { name: 'Whole House', price: 260 },
  r1: { name: 'Room 1', price: 120 },
  r2: { name: 'Room 2', price: 80 },
  r3: { name: 'Room 3', price: 80 },
};
const CLEANING_FEE = 30;
const DEPOSIT = 50;
const HOLD_HOURS = 24;
const TIME_ZONE = 'Asia/Kuala_Lumpur';

const STATUS = {
  awaiting_deposit: 'Awaiting deposit',
  awaiting_approval: 'Awaiting approval',
  confirmed: 'Confirmed',
  denied: 'Declined',
  expired: 'Expired',
  cancelled: 'Cancelled',
};
const METHOD = { qr: 'DuitNow QR', cash: 'Cash' };

const guests = {};
for (const { json } of $input.all()) {
  if (json._id) guests[json._id] = json;
}

const time = (iso) => (iso ? DateTime.fromISO(iso).setZone(TIME_ZONE).toFormat('yyyy-MM-dd HH:mm') : '');
const nightsBetween = (a, b) => Math.round(DateTime.fromISO(b).diff(DateTime.fromISO(a), 'days').days);

const bookings = $('Read recent bookings').all().map(({ json }) => json);
bookings.sort((a, b) => (a.createdAt || '').localeCompare(b.createdAt || ''));

return bookings.map((b) => {
  const room = ROOMS[b.roomId] || { name: b.roomId, price: 0 };
  const nights = nightsBetween(b.checkIn, b.checkOut);
  const total = room.price * nights + CLEANING_FEE;
  // The website shows an unpaid booking as expired once its hold runs out.
  let status = b.status;
  if (status === 'awaiting_deposit' && b.createdAt &&
      DateTime.fromISO(b.createdAt).plus({ hours: HOLD_HOURS }) < DateTime.now()) {
    status = 'expired';
  }
  const guest = guests[b.userId] || {};
  return {
    json: {
      'Booking ID': b._id,
      'Booked at': time(b.createdAt),
      'Room': room.name,
      'Check-in': b.checkIn,
      'Check-out': b.checkOut,
      'Nights': nights,
      'Guests': Number(b.guests),
      'Status': STATUS[status] || status,
      'Total (RM)': total,
      'Deposit (RM)': DEPOSIT,
      'Balance (RM)': total - DEPOSIT,
      'Payment method': METHOD[b.paymentMethod] || b.paymentMethod || '',
      'Payment ref': b.paymentRef || '',
      'Paid at': time(b.paidAt),
      'Guest name': guest.name || '',
      'Phone': guest.phone || '',
      'Email': guest.email || '',
      'Decided at': time(b.decidedAt),
      'Decline reason': b.denyReason || '',
      'Refund due': b.depositRefund ? 'Yes' : '',
      'Cancelled at': time(b.cancelledAt),
      'Last change': time(b._updateTime),
    },
  };
});
